css:
.leanlaunch-container {
    padding: 28px;
    background: linear-gradient(135deg, #1a0533 0%, #0d1b4b 48%, #0a2e1a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #f1f5f9;
}

.leanlaunch-container h1, .leanlaunch-container h2, .leanlaunch-container h3 {
    margin: 0;
    color: #ffffff;
}

.leanlaunch-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 20px;
    padding: 26px 30px;
    margin-bottom: 24px;
}

.leanlaunch-header-left {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.leanlaunch-badge {
    display: inline-block;
    align-self: flex-start;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(167,139,250,0.18);
    border: 1px solid rgba(167,139,250,0.35);
    color: #c4b5fd;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
}

.leanlaunch-header h1 {
    font-size: 1.75rem;
    font-weight: 700;
    background: linear-gradient(135deg, #a78bfa, #60a5fa 55%, #34d399);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.leanlaunch-subtitle {
    margin: 0;
    color: #cbd5e1;
    font-size: 0.95rem;
}

.leanlaunch-header-right {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 8px;
}

.leanlaunch-round-chip {
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
    background: rgba(96,165,250,0.15);
    border: 1px solid rgba(96,165,250,0.35);
    border-radius: 12px;
    padding: 10px 16px;
}

.leanlaunch-round-label {
    color: #93c5fd;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    font-weight: 600;
}

.leanlaunch-round-current {
    font-size: 1.6rem;
    font-weight: 800;
    color: #ffffff;
}

.leanlaunch-round-sep {
    color: #93c5fd;
    font-size: 0.9rem;
}

.leanlaunch-round-max {
    color: #ffffff;
    font-size: 1.05rem;
    font-weight: 600;
}

.leanlaunch-weeks-chip {
    padding: 5px 12px;
    border-radius: 999px;
    background: rgba(52,211,153,0.15);
    border: 1px solid rgba(52,211,153,0.4);
    color: #86efac;
    font-size: 0.78rem;
    font-weight: 600;
    letter-spacing: 0.05em;
}

.leanlaunch-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.leanlaunch-kpi-card {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 16px;
    padding: 20px 22px;
    transition: transform 0.2s ease, background 0.2s ease;
    position: relative;
    overflow: hidden;
}

.leanlaunch-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #a78bfa, #60a5fa);
}

.leanlaunch-kpi-card.leanlaunch-kpi-cash::before { background: linear-gradient(90deg, #34d399, #60a5fa); }
.leanlaunch-kpi-card.leanlaunch-kpi-runway::before { background: linear-gradient(90deg, #60a5fa, #a78bfa); }
.leanlaunch-kpi-card.leanlaunch-kpi-validation::before { background: linear-gradient(90deg, #a78bfa, #f472b6); }
.leanlaunch-kpi-card.leanlaunch-kpi-lois::before { background: linear-gradient(90deg, #fbbf24, #f472b6); }
.leanlaunch-kpi-card.leanlaunch-kpi-paying::before { background: linear-gradient(90deg, #34d399, #fbbf24); }

.leanlaunch-kpi-card:hover {
    background: rgba(255,255,255,0.1);
    transform: translateY(-3px);
}

.leanlaunch-kpi-label {
    color: #94a3b8;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 600;
    margin-bottom: 10px;
}

.leanlaunch-kpi-value {
    font-size: 1.75rem;
    font-weight: 800;
    color: #ffffff;
    letter-spacing: -0.01em;
    line-height: 1.1;
}

.leanlaunch-kpi-sub {
    margin-top: 6px;
    color: #64748b;
    font-size: 0.72rem;
    font-style: italic;
}

.leanlaunch-briefing {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(167,139,250,0.25);
    border-radius: 18px;
    padding: 26px 28px;
    margin-bottom: 20px;
    box-shadow: 0 6px 28px rgba(124,58,237,0.15);
}

.leanlaunch-briefing-top {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    margin-bottom: 14px;
}

.leanlaunch-briefing-tag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 52px;
    height: 52px;
    border-radius: 14px;
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    color: #0f172a;
    font-size: 1.1rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    box-shadow: 0 4px 18px rgba(167,139,250,0.4);
}

.leanlaunch-briefing-titles h2 {
    font-size: 1.4rem;
    font-weight: 700;
    margin-bottom: 2px;
}

.leanlaunch-briefing-subtitle {
    margin: 0;
    color: #cbd5e1;
    font-size: 0.9rem;
}

.leanlaunch-briefing-context {
    color: #e2e8f0;
    font-size: 0.95rem;
    line-height: 1.55;
    margin: 0 0 12px 0;
}

.leanlaunch-briefing-question {
    color: #fde68a;
    font-size: 1rem;
    font-weight: 600;
    margin: 0;
    padding: 10px 14px;
    border-left: 3px solid #fbbf24;
    background: rgba(251,191,36,0.08);
    border-radius: 0 10px 10px 0;
}

.leanlaunch-controls {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 18px;
    padding: 24px 26px;
    margin-bottom: 20px;
}

.leanlaunch-controls h3 {
    font-size: 1.05rem;
    margin-bottom: 16px;
    color: #e0e7ff;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
}

.leanlaunch-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 14px;
}

.leanlaunch-field label {
    color: #cbd5e1;
    font-size: 0.82rem;
    font-weight: 600;
}

.leanlaunch-controls select,
.leanlaunch-controls input[type="number"] {
    background: rgba(15,23,42,0.6);
    border: 1px solid rgba(148,163,184,0.3);
    color: #f1f5f9;
    border-radius: 10px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.leanlaunch-controls select:focus,
.leanlaunch-controls input[type="number"]:focus {
    outline: none;
    border-color: #a78bfa;
    background: rgba(15,23,42,0.85);
    box-shadow: 0 0 0 3px rgba(167,139,250,0.2);
}

.leanlaunch-controls select option {
    background: #1e1b4b;
    color: #f1f5f9;
}

.leanlaunch-buttons {
    display: flex;
    gap: 12px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.leanlaunch-container .btn.btn-primary {
    background: linear-gradient(135deg, #a78bfa, #6366f1);
    border: none;
    border-radius: 10px;
    padding: 11px 22px;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: 0.02em;
    box-shadow: 0 6px 18px rgba(99,102,241,0.35);
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.leanlaunch-container .btn.btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 26px rgba(99,102,241,0.5);
}

.leanlaunch-container .btn.btn-outline-secondary {
    background: transparent;
    border: 1px solid rgba(148,163,184,0.4);
    color: #cbd5e1;
    border-radius: 10px;
    padding: 10px 18px;
    font-weight: 600;
}

.leanlaunch-container .btn.btn-outline-secondary:hover {
    background: rgba(148,163,184,0.15);
    color: #ffffff;
}

.leanlaunch-hint {
    background: rgba(251,191,36,0.08);
    border: 1px solid rgba(251,191,36,0.3);
    border-left: 4px solid #fbbf24;
    border-radius: 12px;
    padding: 14px 18px;
    color: #fde68a;
    font-size: 0.92rem;
    line-height: 1.55;
    margin-bottom: 22px;
    min-height: 52px;
}

.leanlaunch-hint strong {
    color: #fef3c7;
}

.leanlaunch-chart-wrap {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 18px;
    padding: 22px 24px;
    margin-bottom: 22px;
    height: 360px;
}

.leanlaunch-chart-wrap canvas {
    width: 100% !important;
    height: 100% !important;
}

.leanlaunch-history {
    background: rgba(255,255,255,0.04);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 18px;
    padding: 22px 24px;
}

.leanlaunch-history h3 {
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    color: #e0e7ff;
    margin-bottom: 14px;
}

.leanlaunch-history table {
    width: 100%;
    color: #e2e8f0;
    border-collapse: collapse;
}

.leanlaunch-history table thead th {
    color: #94a3b8;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    border-bottom: 1px solid rgba(148,163,184,0.25);
    padding: 10px 12px;
    text-align: left;
}

.leanlaunch-history table tbody td {
    padding: 10px 12px;
    border-bottom: 1px solid rgba(148,163,184,0.1);
    font-size: 0.9rem;
}

.leanlaunch-history table tbody tr:hover {
    background: rgba(255,255,255,0.04);
}

@media (max-width: 768px) {
    .leanlaunch-container { padding: 16px; }
    .leanlaunch-header {
        flex-direction: column;
        align-items: flex-start;
        padding: 20px;
    }
    .leanlaunch-header-right {
        align-items: flex-start;
        width: 100%;
    }
    .leanlaunch-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .leanlaunch-kpi-value { font-size: 1.35rem; }
    .leanlaunch-briefing-top { flex-direction: column; }
    .leanlaunch-chart-wrap { height: 280px; }
}

js:
(function() {
    'use strict';

    const ROUNDS = [
        {
            tag: 'R1',
            weeks: 'Sem. 1–2',
            title: 'Descubrir',
            subtitle: 'Hipótesis y entrevistas de descubrimiento',
            context: 'Runway efectivo: 11 meses. Los 3 conjuntos «comprometidos» (520 unidades) no responden a 4 emails. Comunidades.io acaba de anunciar entrada a Colombia con USD 3M de Serie A. Cero LOIs firmadas, cero clientes pagantes, NPS no medible.',
            question: '¿En qué hipótesis concentrarás la ronda y cuántas entrevistas realizarás?',
            primaryLabel: 'Hipótesis a validar',
            primaryOptions: [
                { value: 'problem',  label: 'Problema — ¿les duele el recaudo manual?' },
                { value: 'solution', label: 'Solución — reacción al prototipo' },
                { value: 'channel',  label: 'Canal — LinkedIn vs. ferias vs. referidos' },
                { value: 'price',    label: 'Precio — willingness-to-pay' }
            ],
            budgetLabel: 'Entrevistas a realizar',
            budgetMin: 3, budgetMax: 30, budgetDefault: 15, budgetStep: 1, budgetUnit: ' entrevistas',
            intensityLabel: 'Estilo de entrevista',
            intensityOptions: [
                { value: 'open',  label: 'Abierta — problema y dolor (Mom Test)' },
                { value: 'demo',  label: 'Con demo — reacción al producto' },
                { value: 'pitch', label: 'Pitch comercial — cerrar LOI' }
            ]
        },
        {
            tag: 'R2',
            weeks: 'Sem. 3–4',
            title: 'Construir',
            subtitle: 'Alcance del MVP bajo restricción de 4 semanas-hombre',
            context: 'El CTO quiere construir integración bancaria PSE (8 semanas). Growth quiere landing + Stripe (1 semana) y medir conversión. La cofundadora administradora propone un «concierge MVP» — cobrar manualmente por WhatsApp mientras se valida. Debes escoger.',
            question: '¿Cuál es el alcance del MVP en las próximas 4 semanas-hombre?',
            primaryLabel: 'Alcance del MVP',
            primaryOptions: [
                { value: 'landing',   label: 'Landing + Stripe (1 sem dev)' },
                { value: 'concierge', label: 'Concierge MVP — recaudo manual (1 sem)' },
                { value: 'core',      label: 'Dashboard de recaudo (3 sem)' },
                { value: 'full',      label: 'Producto completo + integración bancos (8 sem)' }
            ],
            budgetLabel: 'Presupuesto dev (USD)',
            budgetMin: 2000, budgetMax: 60000, budgetDefault: 8000, budgetStep: 500, budgetUnit: ' USD',
            intensityLabel: 'Alcance funcional',
            intensityOptions: [
                { value: 'narrow',   label: 'Narrow — 1 feature central' },
                { value: 'balanced', label: 'Balanced — 2 features' },
                { value: 'wide',     label: 'Wide — 4+ features en paralelo' }
            ]
        },
        {
            tag: 'R3',
            weeks: 'Sem. 5–6',
            title: 'Medir',
            subtitle: 'Experimento y métricas accionables',
            context: 'Tienes prototipo y 5 administradoras dispuestas a «ver una demo». Debes definir ex-ante qué métrica importa, qué umbral valida y cuántos conjuntos meter al experimento. Recuerda la regla: feedback positivo ≠ demanda.',
            question: '¿Cuál es tu métrica principal y tu umbral de validación ex-ante?',
            primaryLabel: 'Métrica principal',
            primaryOptions: [
                { value: 'trial_to_paid', label: 'Trial-to-paid — accionable' },
                { value: 'loi_signed',    label: 'LOIs firmadas — accionable' },
                { value: 'ctr',           label: 'CTR del landing — métrica de vanidad' },
                { value: 'followers',     label: 'Seguidores LinkedIn — métrica de vanidad' }
            ],
            budgetLabel: 'Conjuntos en el experimento',
            budgetMin: 1, budgetMax: 15, budgetDefault: 5, budgetStep: 1, budgetUnit: ' conjuntos',
            intensityLabel: 'Umbral de validación',
            intensityOptions: [
                { value: 'strict', label: 'Estricto — ≥3 LOIs pagadas o pivotamos' },
                { value: 'medium', label: 'Medio — ≥1 LOI firmada' },
                { value: 'loose',  label: 'Flojo — feedback positivo basta' }
            ]
        },
        {
            tag: 'R4',
            weeks: 'Sem. 7–10',
            title: 'Aprender y decidir',
            subtitle: 'Persevere · Pivot · Kill',
            context: 'Datos del experimento: CTR 3.2%, demo-to-trial 18%, trial-to-paid 0% (0 de los conjuntos probados pagaron). La competencia Comunidades.io confirma lanzamiento Bogotá Q3. Runway restante estimado: 7 meses si sigues.',
            question: 'Con esta evidencia, ¿qué haces? Tu decisión debe poderse defender con la regla de Ronda 3.',
            primaryLabel: 'Decisión',
            primaryOptions: [
                { value: 'persevere',      label: 'Persevere — ajustar onboarding' },
                { value: 'zoom_in',        label: 'Zoom-in — doblar la feature que sí traccionó' },
                { value: 'zoom_out',       label: 'Zoom-out — plataforma más amplia' },
                { value: 'customer_pivot', label: 'Customer pivot — saltar a PyMEs de servicios' },
                { value: 'problem_pivot',  label: 'Problem pivot — otro dolor del mismo segmento' },
                { value: 'kill',           label: 'Kill — devolver el capital no gastado' }
            ],
            budgetLabel: 'Presupuesto próxima ronda (USD)',
            budgetMin: 0, budgetMax: 80000, budgetDefault: 20000, budgetStep: 1000, budgetUnit: ' USD',
            intensityLabel: 'Base de la decisión',
            intensityOptions: [
                { value: 'data',   label: 'Datos — métricas pre-definidas' },
                { value: 'hybrid', label: 'Mixta — datos + señales cualitativas' },
                { value: 'gut',    label: 'Intuición — visión del fundador' }
            ]
        },
        {
            tag: 'R5',
            weeks: 'Sem. 11–12',
            title: 'Pitch al inversionista',
            subtitle: 'Pedir 6 meses más de runway a Ruta N',
            context: 'Tienes 12 minutos con un socio de Ruta N. Debes justificar las 4 rondas previas, pedir un ticket y prometer un milestone a 6 meses. Hará 3 preguntas filosas: ¿qué hipótesis falsificaron?, ¿qué les costó más?, ¿por qué nosotros y no Comunidades.io?',
            question: '¿Con qué narrativa pitchearás y qué milestone concreto pedirás financiar?',
            primaryLabel: 'Narrativa del pitch',
            primaryOptions: [
                { value: 'learning',  label: 'Aprendizaje — qué hipótesis falsificamos' },
                { value: 'traction',  label: 'Tracción — LOIs y demo-to-trial' },
                { value: 'vision',    label: 'Visión — mercado LATAM y team' },
                { value: 'optimism',  label: 'Optimismo — «casi lo logramos»' }
            ],
            budgetLabel: 'Ask al inversionista (USD)',
            budgetMin: 50000, budgetMax: 2000000, budgetDefault: 300000, budgetStep: 25000, budgetUnit: ' USD',
            intensityLabel: 'Milestone 6 meses',
            intensityOptions: [
                { value: 'paying',  label: '10 conjuntos pagando MRR' },
                { value: 'loi',     label: '25 LOIs firmadas' },
                { value: 'mau',     label: '500 MAU en el prototipo' },
                { value: 'feature', label: 'Integración bancaria PSE en producción' }
            ]
        }
    ];

    class LeanLaunchAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'LeanLaunch — NiduApp';
            this.version = '1.1.0';
            this.ROUNDS = ROUNDS;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 198000,
                    burnRate: 18000,
                    runway: 11.0,
                    validation: 0,
                    lois: 0,
                    paying: 0,
                    hypothesesValidated: 0,
                    pivotCount: 0,
                    killed: false,
                    zoomSignal: 0,
                    validationHistory: [],
                    runwayHistory: [],
                    cashHistory: [],
                    roundNotes: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primary: 'problem',
                    budget: 15,
                    intensity: 'open'
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 60);
        }

        validateDecisions(decisions) {
            const p = document.getElementById('primaryInput');
            const b = document.getElementById('budgetInput');
            const i = document.getElementById('intensityInput');
            if (p) decisions.primary = p.value;
            if (b) decisions.budget = parseFloat(b.value);
            if (i) decisions.intensity = i.value;

            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const spec = this.ROUNDS[Math.min(round - 1, this.ROUNDS.length - 1)];

            if (!decisions.primary) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_primary'), 'warning');
                return false;
            }
            if (isNaN(decisions.budget) || decisions.budget < spec.budgetMin || decisions.budget > spec.budgetMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_budget'), 'warning');
                return false;
            }
            if (!decisions.intensity) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warn_intensity'), 'warning');
                return false;
            }

            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let validationDelta = 0;
            let cashSpend = 9000; // 2 weeks of burn per round (burn 18K/mo)
            let loisDelta = 0;
            let payingDelta = 0;
            let hypothesesValidated = 0;
            let note = '';

            if (round === 1) {
                const scores = {
                    problem:  { open: 22, demo: 14, pitch:  6 },
                    solution: { open: 10, demo: 15, pitch:  6 },
                    channel:  { open:  8, demo:  6, pitch:  5 },
                    price:    { open: 10, demo:  8, pitch: -4 }
                };
                validationDelta = scores[d.primary][d.intensity];
                if (d.budget < 8) validationDelta -= 6;
                else if (d.budget >= 15) validationDelta += 3;

                cashSpend += 120 * d.budget + 1500;

                if (d.primary === 'problem' && d.intensity === 'open' && d.budget >= 12) {
                    loisDelta = 1;
                    hypothesesValidated = 1;
                    ds.zoomSignal += 2;
                    note = 'Problema validado: 2 dolores recurrentes confirmados (cartera vencida y conciliación bancaria). 1 LOI verbal.';
                } else if (d.primary === 'solution' && d.intensity === 'demo') {
                    ds.zoomSignal += 1;
                    note = 'Señal de entusiasmo con la demo, pero cero compromiso escrito. Riesgo de sesgo de cortesía.';
                } else if (d.primary === 'price' && d.intensity === 'pitch') {
                    note = 'Pitcheaste precio antes de validar el problema. Respuestas dominadas por «suena interesante».';
                } else if (d.budget < 8) {
                    note = 'Pocas entrevistas para concluir. Aprendizaje superficial, decisiones a ciegas.';
                } else {
                    note = 'Aprendizaje mixto. Revisa si el patrón que viste es dolor real o cortesía.';
                }
            } else if (round === 2) {
                const scopeCost = { landing: 3000, concierge: 1500, core: 14000, full: 38000 };
                const scopeVal  = { landing: 14, concierge: 22, core: 6, full: -14 };
                validationDelta = scopeVal[d.primary] || 0;
                cashSpend += scopeCost[d.primary] || 5000;

                if (d.intensity === 'narrow')       validationDelta += 4;
                else if (d.intensity === 'wide')    validationDelta -= 6;

                if (ds.hypothesesValidated === 0 && (d.primary === 'core' || d.primary === 'full')) {
                    validationDelta -= 10;
                    note = 'Construiste antes de validar el problema. Semanas-hombre invertidas sin evidencia de dolor real.';
                } else if (d.primary === 'concierge') {
                    loisDelta = 1;
                    ds.zoomSignal += 2;
                    note = 'Concierge MVP: aprendizaje profundo, cero deuda técnica, 1 LOI convertida en pre-pago parcial.';
                } else if (d.primary === 'landing') {
                    ds.zoomSignal += 1;
                    note = 'Landing + Stripe: mides conversión en días. Útil si Ronda 1 validó el problema.';
                } else if (d.primary === 'core') {
                    note = 'Dashboard de recaudo. Funcional pero sin validación transversal.';
                } else if (d.primary === 'full') {
                    note = 'Producto completo construido. 0 clientes para probarlo. Clásico error de Lean Startup.';
                }
                if (d.budget < (scopeCost[d.primary] || 5000) * 0.6) {
                    validationDelta -= 4;
                    note += '<br>Presupuesto insuficiente: entregable a medias, moral del equipo afectada.';
                }
            } else if (round === 3) {
                const metricVal = { trial_to_paid: 20, loi_signed: 18, ctr: 4, followers: -2 };
                const thresholdVal = { strict: 6, medium: 2, loose: -8 };
                validationDelta = (metricVal[d.primary] || 0) + (thresholdVal[d.intensity] || 0);
                cashSpend += 1200 * d.budget + 800;

                if (d.primary === 'ctr' || d.primary === 'followers') {
                    note = 'Métrica de vanidad como principal. Riesgo real de celebrar ruido y racionalizar un fracaso.';
                } else if (d.intensity === 'strict') {
                    hypothesesValidated += 1;
                    note = 'Umbral ex-ante bien definido. Te obliga a decidir sin sesgo post-hoc.';
                } else if (d.intensity === 'loose') {
                    note = 'Umbral flojo invita a racionalizar. En Ronda 4 te costará tomar la decisión.';
                } else {
                    note = 'Umbral medio razonable, pero deja espacio a interpretación subjetiva.';
                }

                // El experimento entrega datos reales: trial-to-paid 0%
                if (d.primary === 'trial_to_paid') {
                    note += '<br>Resultado experimento: trial-to-paid 0% (0 de ' + d.budget + ' conjuntos pagaron).';
                } else if (d.primary === 'loi_signed') {
                    loisDelta = Math.min(Math.floor(d.budget / 3), 2);
                    note += '<br>Resultado experimento: ' + loisDelta + ' LOIs firmadas sobre ' + d.budget + ' conjuntos.';
                } else if (d.primary === 'ctr') {
                    note += '<br>Resultado: CTR 3.2% (no dice nada sobre demanda real).';
                } else {
                    note += '<br>Resultado: +180 seguidores (no dice nada sobre demanda real).';
                }
            } else if (round === 4) {
                const decisionScores = {
                    persevere:      -12,
                    zoom_in:        ds.zoomSignal >= 2 ? 18 : 6,
                    zoom_out:        -4,
                    customer_pivot: ds.hypothesesValidated >= 2 ? 4 : -16,
                    problem_pivot:   ds.hypothesesValidated >= 1 ? 10 : -6,
                    kill:           ds.runway < 5 ? 8 : -14
                };
                validationDelta = decisionScores[d.primary] || 0;
                if (d.intensity === 'data')      validationDelta += 5;
                else if (d.intensity === 'gut')  validationDelta -= 4;

                // Inversión próxima ronda aplicada parcialmente
                cashSpend += Math.min(Math.max(d.budget, 0), 80000) * 0.35;

                if (d.primary === 'persevere') {
                    note = 'Persevere con trial-to-paid 0%. Clásico sesgo de continuación frente a evidencia negativa. El onboarding no es el problema.';
                } else if (d.primary === 'zoom_in') {
                    ds.pivotCount += 1;
                    note = ds.zoomSignal >= 2
                        ? 'Zoom-in a la feature que sí mostró tracción. Pivot disciplinado con evidencia.'
                        : 'Zoom-in sin señal previa sólida. Estás escogiendo «algo» por no decidir.';
                } else if (d.primary === 'zoom_out') {
                    ds.pivotCount += 1;
                    note = 'Zoom-out amplía la propuesta antes de validarla. Riesgo de repetir el error en mayor escala.';
                } else if (d.primary === 'customer_pivot') {
                    ds.pivotCount += 1;
                    ds.hypothesesValidated = Math.max(0, ds.hypothesesValidated - 1);
                    note = ds.hypothesesValidated >= 1
                        ? 'Customer pivot con alguna validación previa. Necesitas re-validar hipótesis con PyMEs desde cero.'
                        : 'Pivot a PyMEs sin evidencia del nuevo segmento. Repites el error del principio en un segmento nuevo.';
                } else if (d.primary === 'problem_pivot') {
                    ds.pivotCount += 1;
                    note = 'Problem pivot dentro del mismo segmento. Aprovecha el conocimiento de administradoras, ataca otro dolor.';
                } else if (d.primary === 'kill') {
                    if (ds.runway >= 5) {
                        ds.killed = true;
                        note = 'Kill prematuro con ' + ds.runway.toFixed(1) + ' meses de runway por usar. Mataste una hipótesis, no la empresa.';
                    } else {
                        note = 'Kill con runway corto: decisión honesta, capital residual devuelto a LPs.';
                    }
                }
            } else if (round === 5) {
                if (ds.killed) {
                    validationDelta = -5;
                    cashSpend = 600;
                    note = 'Empresa cerrada en Ronda 4. El pitch se convierte en post-mortem con el inversionista.';
                } else {
                    const narrativeScores = { learning: 18, traction: 12, vision: 4, optimism: -10 };
                    const milestoneScores = { paying: 10, loi: 6, mau: -2, feature: -6 };
                    validationDelta = (narrativeScores[d.primary] || 0) + (milestoneScores[d.intensity] || 0);

                    const askRealism = (d.budget >= 150000 && d.budget <= 600000) ? 5 : (d.budget > 1200000 ? -8 : -3);
                    validationDelta += askRealism;
                    cashSpend = 800;

                    if (d.primary === 'learning' && d.intensity === 'paying' && askRealism > 0) {
                        note = 'Pitch honesto con milestone medible y ask realista. El socio pide term-sheet follow-up.';
                    } else if (d.primary === 'optimism') {
                        note = '«Casi lo logramos» no compra runway. El inversionista pide datos que no tienes.';
                    } else if (d.intensity === 'feature') {
                        note = 'Milestone orientado a entregable técnico, no a demanda. El inversionista pregunta: ¿y quién paga?';
                    } else if (askRealism < 0 && d.budget > 1200000) {
                        note = 'Ask desproporcionado al stage. El inversionista cierra la conversación.';
                    } else {
                        note = 'Pitch recibido con reservas. Follow-up condicionado a cumplir milestones cuantitativos.';
                    }
                }
            }

            ds.cash = Math.max(0, ds.cash - cashSpend);
            ds.validation = Math.max(0, Math.min(100, (ds.validation || 0) + validationDelta));
            ds.lois = (ds.lois || 0) + loisDelta;
            ds.paying = (ds.paying || 0) + payingDelta;
            ds.hypothesesValidated = (ds.hypothesesValidated || 0) + hypothesesValidated;
            ds.runway = ds.cash > 0 ? parseFloat((ds.cash / ds.burnRate).toFixed(2)) : 0;

            ds.validationHistory.push(ds.validation);
            ds.runwayHistory.push(parseFloat(ds.runway.toFixed(1)));
            ds.cashHistory.push(Math.round(ds.cash));
            ds.roundNotes.push(note);

            const result = {
                period: round,
                primary: d.primary,
                intensity: d.intensity,
                budget: d.budget,
                cashSpend: Math.round(cashSpend),
                validationDelta: Math.round(validationDelta),
                validation: Math.round(ds.validation),
                lois: ds.lois,
                paying: ds.paying,
                runway: parseFloat(ds.runway.toFixed(1)),
                cash: Math.round(ds.cash),
                note: note
            };

            var _sc = this._score(ds);
            ds.score = _sc;
            ds.performance = { overallScore: _sc, grade: this._grade(_sc) };
            result.score = _sc;
            result.overallScore = _sc;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: round + 1 });
                self._renderHint(result, ds);
            }, 500);

            return result;
        }

        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            const idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            const r = this.ROUNDS[idx];
            const g = function(id) { return document.getElementById(id); };

            if (g('roundTag')) g('roundTag').textContent = r.tag;
            if (g('roundWeeks')) g('roundWeeks').textContent = r.weeks;
            if (g('roundTitle')) g('roundTitle').textContent = r.title;
            if (g('roundSubtitle')) g('roundSubtitle').textContent = r.subtitle;
            if (g('roundContext')) g('roundContext').textContent = r.context;
            if (g('roundQuestion')) g('roundQuestion').textContent = r.question;
            if (g('primaryLabel')) g('primaryLabel').textContent = r.primaryLabel;
            if (g('budgetLabel')) g('budgetLabel').textContent = r.budgetLabel + ' (' + r.budgetMin + '–' + r.budgetMax + r.budgetUnit + ')';
            if (g('intensityLabel')) g('intensityLabel').textContent = r.intensityLabel;

            const primary = g('primaryInput');
            if (primary) {
                primary.innerHTML = '';
                r.primaryOptions.forEach(function(o) {
                    const opt = document.createElement('option');
                    opt.value = o.value;
                    opt.textContent = o.label;
                    primary.appendChild(opt);
                });
                primary.value = r.primaryOptions[0].value;
            }

            const intensity = g('intensityInput');
            if (intensity) {
                intensity.innerHTML = '';
                r.intensityOptions.forEach(function(o) {
                    const opt = document.createElement('option');
                    opt.value = o.value;
                    opt.textContent = o.label;
                    intensity.appendChild(opt);
                });
                intensity.value = r.intensityOptions[0].value;
            }

            const budget = g('budgetInput');
            if (budget) {
                budget.min = r.budgetMin;
                budget.max = r.budgetMax;
                budget.step = r.budgetStep || 1;
                budget.value = r.budgetDefault;
            }
        }

        _renderHint(result, ds) {
            const hint = document.getElementById('hintBox');
            if (!hint) return;
            let msg = '';
            if (result.note) msg += '<strong>Nota del facilitador:</strong> ' + result.note;
            if (ds.runway < 4 && ds.runway > 0) msg += '<br>⚠ Runway bajo: ' + ds.runway.toFixed(1) + ' meses. Toda próxima decisión debe ser financiable.';
            if (ds.validation < 20 && result.period >= 2) msg += '<br>📉 Validación débil: revisa si estás aprendiendo o solo construyendo.';
            if (ds.killed) msg += '<br>🛑 NiduApp cerrada. Capital residual devuelto.';
            hint.innerHTML = msg || '<em>Sin alertas — sigue iterando.</em>';
        }

